// Abgabenordnung – Aufgaben Teil 2: Verwaltungsakt, Wirksamkeit, Bekanntgabe, Vorbehalt/Vorläufigkeit/Anmeldung,
// gesonderte Feststellung, Zuständigkeit, Fristen, Erhebung und Klausurfälle. Rechtsstand 2026.
import { A, R, F, D, M, eur, tagUTC, plusTage, plusMonate, istFrei, werktag, lang, kurz, warumFrei, reformationstag } from "./hilfen.js";

/** Zufälliger Werktag 2026 (Januar bis Mitte November), an dem ein Bescheid zur Post gegeben wird. */
const postTag = (r) => { for (;;) { const p = plusTage(tagUTC(2026, 1, 5), r.zahl(0, 314)); if (!istFrei(p)) return p; } };
/** Bekanntgabe nach § 122 Abs. 2 Nr. 1 AO mit Verschiebung nach § 108 Abs. 3 AO. */
const bekanntgabe = (p) => { const fiktiv = plusTage(p, 4); return { fiktiv, bek: werktag(fiktiv) }; };
const verschoben = (x, y, norm = "§ 108 Abs. 3 AO") => (x.getTime() === y.getTime() ? "" : ` Das ist ein ${warumFrei(x)} → nächster Werktag: ${lang(y)} (${norm}).`);

// ======================================================================= Verwaltungsakt, Steuerbescheid, Nebenbestimmungen
